-- ==================================================================
-- PERSISTENCIA DE PROPUESTAS CURRICULARES MIG EN POSTGRESQL (HETZNER)
-- Compatible con Apache Superset (jfbernalp.dev)
-- ==================================================================

DROP VIEW IF EXISTS view_superset_kpis_curriculares_mig CASCADE;
DROP VIEW IF EXISTS view_superset_malla_curricular_mig CASCADE;
DROP VIEW IF EXISTS view_superset_oferta_academica_mig CASCADE;
DROP TABLE IF EXISTS historial_revisiones_curriculo CASCADE;
DROP TABLE IF EXISTS dim_docentes_propuestas_mig CASCADE;
DROP TABLE IF EXISTS fact_modulos_propuestas_mig CASCADE;
DROP TABLE IF EXISTS dim_propuestas_curriculares_mig CASCADE;
DROP TABLE IF EXISTS fact_diagnostico_ia CASCADE;

CREATE TABLE fact_diagnostico_ia (
    id SERIAL PRIMARY KEY,
    programa_evaluado VARCHAR(200),
    puntuacion_competitividad NUMERIC(5,2),
    resumen_ejecutivo TEXT,
    fecha_generacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE dim_propuestas_curriculares_mig (
    id_propuesta VARCHAR(64) PRIMARY KEY,
    tipo_propuesta VARCHAR(100),
    nombre_programa VARCHAR(250),
    titulo_otorgado VARCHAR(250),
    nivel_academico VARCHAR(100),
    duracion_estimada VARCHAR(100),
    creditos_totales INTEGER,
    horas_totales INTEGER,
    modalidad VARCHAR(100),
    horario TEXT,
    fecha_inicio_estimada VARCHAR(100),
    fecha_terminacion_estimada VARCHAR(100),
    proximas_ediciones VARCHAR(150),
    inversion_publico_externo TEXT,
    inversion_comunidad_unicafam TEXT,
    inversion_egresados TEXT,
    inversion_grupos TEXT,
    justificacion_detallada TEXT,
    objetivos_programa TEXT,
    dirigido_a TEXT,
    metodologia_detallada TEXT,
    valores_agregados TEXT,
    perfil_ingreso TEXT,
    perfil_egreso TEXT,
    roles_objetivo TEXT,
    impacto_salarial_proyectado TEXT,
    url_descarga_excel TEXT,
    estado VARCHAR(50) DEFAULT 'PENDIENTE_REVISION',
    version INTEGER DEFAULT 1,
    aprobado_por VARCHAR(150),
    fecha_decision VARCHAR(50),
    motivo_rechazo TEXT
);

CREATE TABLE historial_revisiones_curriculo (
    id SERIAL PRIMARY KEY,
    id_propuesta VARCHAR(64) REFERENCES dim_propuestas_curriculares_mig(id_propuesta) ON DELETE CASCADE,
    version_resultante INTEGER,
    usuario_aprobador VARCHAR(150),
    rol_usuario VARCHAR(100),
    decision VARCHAR(50),
    comentarios_feedback TEXT,
    cambios_aplicados_resumen TEXT,
    fecha_registro VARCHAR(50)
);

CREATE TABLE fact_modulos_propuestas_mig (
    id_modulo SERIAL PRIMARY KEY,
    id_propuesta VARCHAR(64) REFERENCES dim_propuestas_curriculares_mig(id_propuesta) ON DELETE CASCADE,
    numero_modulo INTEGER,
    nombre_modulo VARCHAR(250),
    semestre_sugerido VARCHAR(50),
    creditos INTEGER,
    horas_tfd INTEGER,
    horas_tti INTEGER,
    horas_totales_modulo INTEGER,
    contenido_detallado TEXT,
    cronograma_fechas TEXT,
    stack_tecnologico TEXT,
    raes TEXT,
    justificacion_mercado TEXT
);

CREATE TABLE dim_docentes_propuestas_mig (
    id_docente SERIAL PRIMARY KEY,
    id_propuesta VARCHAR(64) REFERENCES dim_propuestas_curriculares_mig(id_propuesta) ON DELETE CASCADE,
    nombre_o_rol VARCHAR(250),
    modulo_asignado VARCHAR(250),
    perfil_experto TEXT
);

INSERT INTO fact_diagnostico_ia (programa_evaluado, puntuacion_competitividad, resumen_ejecutivo) VALUES ('Tecnología en Análisis y Gestión de Datos', 52.0, 'El ecosistema de formación en datos de UniCafam (Tecnología en Análisis y Gestión de Datos, articulado por ciclo propedéutico al Profesional en Ciencia de Datos) posee bases curriculares extraordinariamente competitivas. El programa actual cubre con rigor competencias clave en Python, SQL, NLP, Machine Learning y visualización con Power BI/Tableau, alcanzando una cobertura de mercado del 52.0%. No obstante, el Observatorio Laboral revela una brecha salarial abismal entre el mercado local colombiano ($4.516.768 COP promedio) y el mercado remoto internacional ($32.943.043 COP promedio). Las vacantes de alto valor (salarios superiores a $11.000.000 COP local y hasta $68.000.000 COP remoto) exigen competencias de ingeniería y operaciones que actualmente no forman parte del núcleo básico del tecnólogo. Para capitalizar el 48% restante del mercado, la institución debe proyectar una ruta de profundización y posgrado enfocada en: 1) Infraestructura Cloud Enterprise (AWS, GCP, Azure), 2) Prácticas de MLOps y contenedorización (Docker, Kubernetes, MLflow), 3) Big Data Distribuido a gran escala (Databricks, Spark) y 4) IA Generativa aplicada a nivel empresarial. Esta estrategia curricular no reemplaza nuestras fortalezas actuales; las potencia, garantizando el cumplimiento de la reglamentación del Ministerio de Educación Nacional (Decreto 1330) y asegurando que nuestros egresados de tecnología escalen orgánicamente hacia roles profesionales y de posgrado de máxima remuneración global.');

INSERT INTO dim_propuestas_curriculares_mig VALUES ('PROP_01', 'Electiva de Profundización', 'Implementación de Arquitecturas Cloud y MLOps', 'Certificado de Profundización en Cloud Data Engineering & MLOps', 'Pregrado', '1 semestre', 6, 288, 'Híbrida / PAT (Presencialidad Asistida por Tecnología)', 'Sábados de 7:00 a.m. a 1:00 p.m. / Sesiones sincrónicas virtuales y laboratorios presenciales bimensuales', 'Febrero de 2025', 'Junio de 2025', 'Cohortes en el primer y segundo semestre de cada año académico', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'La tecnología en Análisis y Gestión de Datos de UniCafam forma tecnólogos con excelente dominio en habilidades consolidadas como SQL (presente en el 62.3% de las ofertas, n=355) y Python (56.7%, n=323) según el Observatorio de Empleo UniCafam (corte 2026-10-28). Sin embargo, la creciente demanda de flujos integrados exige competencias en ETL / Pipelines de Datos (45.4%, n=259) e infraestructura en la nube como AWS (23.5%, n=134) y GCP (19.1%, n=109). Para roles clave como Ingeniero de Datos (25.6% de las ofertas del mercado, n=146) y Machine Learning / AI Engineer (18.2%, n=104), se vuelve indispensable automatizar pipelines e implementar prácticas de MLOps (7.4%, n=42). Introducir esta electiva de 6 créditos en el ciclo profesional articula las fortalezas analíticas de UniCafam con las necesidades operativas de la industria cloud.', 'Objetivo General: Desarrollar competencias teórico-prácticas en la estructuración de flujos de datos automatizados y despliegue continuo de modelos de Machine Learning en entornos de computación en la nube empresariales.
Objetivo Específico 1: Implementar arquitecturas de almacenamiento y procesamiento serverless en AWS y GCP para canalizar volúmenes de datos a escala.
Objetivo Específico 2: Contenedorizar aplicaciones de IA utilizando Docker y desplegar microservicios eficientes accesibles a través de APIs web.
Objetivo Específico 3: Diseñar ciclos de vida automatizados de modelos (MLOps) integrando herramientas de tracking como MLflow y pipelines básicos de CI/CD.', 'Estudiantes de 5to semestre de la Tecnología en Análisis y Gestión de Datos, estudiantes de Ingeniería de Sistemas de UniCafam y egresados tecnólogos de datos que dominen Python intermedio y bases de datos relacionales.', 'Modelo pedagógico activo basado en retos (PBL - Project Based Learning). Los estudiantes desarrollarán un proyecto integrador a lo largo del semestre consistente en tomar un modelo predictivo previamente entrenado en su carrera, empaquetarlo en un contenedor Docker, desplegarlo como microservicio en AWS, y configurar su respectivo pipeline de control, monitoreo y CI/CD utilizando GitHub Actions y MLflow. Las clases constan de un 30% de conceptualización y un 70% de talleres aplicados en laboratorios cloud (AWS Academy y Google Cloud for Education).', 'Acceso gratuito a entornos sandbox de AWS y Google Cloud a través de convenios educativos de UniCafam.
Voucher de descuento de hasta el 50% para la certificación oficial AWS Certified Cloud Practitioner o GCP Associate Cloud Engineer.
Desarrollo de un portafolio de producción alojado en GitHub listo para ser presentado en procesos de selección internacional.', 'Estudiante o profesional del área de tecnología/sistemas con conocimientos demostrables en programación estructurada en Python (estructuras de datos, funciones, Pandas) y fundamentos conceptuales de bases de datos relacionales y Machine Learning básico.', 'Al finalizar la electiva, el egresado será capaz de aprovisionar infraestructura de computación y almacenamiento en la nube, diseñar canalizaciones de datos (pipelines) automatizadas, empaquetar algoritmos en contenedores portables y desplegar servicios web que expongan modelos analíticos listos para el consumo empresarial.', 'Ingeniero de Datos (Data Engineer), Machine Learning / AI Engineer, Practicante de Operaciones de Machine Learning (MLOps Practitioner)', 'Dato no disponible: el observatorio no tiene una prima concluyente para estos roles (corte 2026-10-28). La mediana salarial general para el mercado local en Colombia es de $4.478.000 COP (n=133) y para el mercado internacional remoto es de $14.600.000 COP (n=11).', 'https://jfbernalp.dev/downloads/mig/PROP_01_MIG.xlsx', 'PENDIENTE_REVISION', 2, '', '2026-10-28 01:42:09', '');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_01', 1, 'Sistema Observatorio IA UniCafam', 'Motor Generativo (Gemini 3.5 Flash)', 'CREACION_INICIAL', 'Generación curricular inicial groundeada en datos del mercado laboral y Decreto 1330 MEN.', 'Diseño base de microcurrículos, RAEs y perfil docente.', '2026-10-03 12:00:00');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_01', 1, 'Dr. Carlos Alberto Gómez', 'Decano Escuela de Ingeniería y Tecnología', 'APROBADO', 'Aprobación formal otorgada por Dr. Carlos Alberto Gómez (Decano Escuela de Ingeniería y Tecnología). Propuesta habilitada para despliegue público y radicación oficial MIG.', 'Cambio de estado formal en el flujo de aprobación.', '2026-10-16 17:34:04');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_01', 1, 'Decanatura / Comité Curricular UniCafam', 'Usuario Aprobador', 'REAPERTURA_REVISION', 'Propuesta reabierta para nueva deliberación o ajustes curriculares.', 'Estado retornado a PENDIENTE_REVISION.', '2026-10-24 08:51:23');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_01', 2, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'SOLICITUD_AJUSTE', 'Regeneración institucional con el contexto de mercado verificado del observatorio. Mantenga el tipo de programa, su nivel, créditos y horas. Revise el enfoque y los módulos a la luz de la demanda de habilidades y de los roles del contexto, y reemplace TODAS las cifras de mercado por cifras del contexto (con su n y el corte) o por ''Dato no disponible en el observatorio''. Tarifas: ''Por definir según tarifario institucional''.', 'Se reemplazaron todas las cifras y afirmaciones no respaldadas por los datos oficiales del Observatorio de Empleo UniCafam (corte 2026-10-28). Se incluyó el número de ofertas (n) y los porcentajes exactos de la demanda por habilidad y rol. El impacto salarial se ajustó a ''Dato no disponible'' por falta de una prima concluyente para los roles objetivo, citando únicamente las medianas de mercado con su respectivo n. La estructura de precios en ''inversion'' fue actualizada a ''Por definir según tarifario institucional''. Se mantuvieron intactos los créditos (6), horas totales (288), la estructura modular y los objetivos según la normativa institucional y el Decreto 1330 MEN.', '2026-10-28 01:42:09');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_01', 1, 'Cloud Data Engineering (AWS & GCP Foundations)', '5', 3, 48, 96, 144, '1. Fundamentos de nube e Infraestructura Global.
2. Almacenamiento de datos escalable en AWS (S3) y GCP (Cloud Storage).
3. Bases de datos modernas y Data Warehousing (Amazon Redshift, Google BigQuery).
4. Orquestación serverless y ETL en la nube (AWS Glue, Cloud Dataflow).
5. Seguridad, gobernanza de datos y manejo de accesos (IAM).', 'Semanas 1 a 8', 'AWS S3, Google Cloud Storage, BigQuery, AWS Glue, IAM', 'Diseñar arquitecturas de almacenamiento híbrido utilizando servicios de nubes públicas líderes que soporten las necesidades analíticas de una organización. | Estructurar procesos ETL serverless para la ingesta, transformación y carga de bases de datos analíticas a gran escala.', 'Responde a la demanda directa de habilidades clave según el Observatorio (corte 2026-10-28): ETL / Pipelines de Datos está presente en el 45.4% de las ofertas (n=259), AWS en el 23.5% (n=134) y Google Cloud en el 19.1% (n=109). Además, el rol de Ingeniero de Datos representa el 25.6% de las vacantes totales (n=146).');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_01', 2, 'MLOps & Despliegue de Modelos de IA', '5', 3, 48, 96, 144, '1. Introducción al ciclo de vida de MLOps y comparación con DevOps.
2. Creación de APIs web para consumo de modelos (FastAPI, Flask).
3. Contenedorización de aplicaciones y entornos aislados de desarrollo con Docker.
4. Tracking de experimentos, almacenamiento de artefactos y registro de modelos con MLflow.
5. Monitoreo básico del comportamiento del modelo en producción (Data Drift e inferencia).', 'Semanas 9 a 16', 'Docker, FastAPI, MLflow, GitHub Actions', 'Empaquetar aplicaciones analíticas y modelos de Machine Learning dentro de contenedores estandarizados que aseguren su portabilidad entre diferentes plataformas. | Implementar flujos continuos de control de versiones y despliegue automatizado para el monitoreo sistemático de la degradación de modelos en producción.', 'Alineado con las competencias requeridas para Machine Learning / AI Engineer (18.2% de ofertas, n=104). La habilidad de MLOps aparece en el 7.4% de ofertas (n=42) y Docker/Kubernetes en el 5.1% (n=29), siendo habilidades especializadas en el ecosistema técnico actual.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_01', 'Especialista en Infraestructura de Datos Cloud', 'Cloud Data Engineering (AWS & GCP Foundations)', 'Ingeniero de Sistemas o de Datos con especialización o maestría en áreas afines, certificado oficialmente como AWS Certified Solutions Architect o GCP Professional Cloud Architect, con experiencia laboral mínima de 4 años en el sector corporativo diseñando pipelines en la nube.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_01', 'Ingeniero de Plataformas AI / MLOps Lead', 'MLOps & Despliegue de Modelos de IA', 'Científico de Datos Senior o MLOps Engineer con experiencia laboral de más de 5 años en despliegue de modelos a gran escala, dominio experto en metodologías ágiles de ingeniería de software, empaquetamiento con Docker y orquestadores.');
INSERT INTO dim_propuestas_curriculares_mig VALUES ('PROP_02', 'Microcredencial / Certificación Corta', 'IA Generativa y Arquitecturas RAG para Negocios', 'Certificación Universitaria de Especialista en IA Generativa & Arquitecturas RAG para Negocios', 'Educación Continua / Formación Avanzada', '8 semanas', 2, 96, '100% Virtual con mentorías semanales sincrónicas', 'Martes y Jueves de 6:00 p.m. a 9:00 p.m. (Virtual Sincrónico)', 'Abril de 2025', 'Junio de 2025', 'Tres ediciones anuales planificadas (Febrero, Junio, Septiembre)', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'La Inteligencia Artificial Generativa y los Modelos de Lenguaje de Gran Escala (LLMs) están redefiniendo la eficiencia operativa en el sector empresarial. Según el Observatorio de Empleo UniCafam (corte 2026-10-28, n=570 ofertas), Python presenta una alta demanda situándose en un 56.7% de las ofertas (323 ofertas), seguido por habilidades clave como SQL en un 62.3% (355 ofertas) y ETL / Pipelines de Datos en un 45.4% (259 ofertas). Por su parte, la habilidad de NLP / LLMs se encuentra en un 6.1% de las ofertas (35 ofertas), AWS en un 23.5% (134 ofertas) y Azure en un 24.0% (137 ofertas). Esta microcredencial articula las competencias en Python y bases de datos con arquitecturas avanzadas como Retrieval-Augmented Generation (RAG), almacenamiento en bases de datos vectoriales y orquestación cognitiva, permitiendo integrar soluciones desplegadas en servicios cloud y respaldadas en repositorios públicos para fortalecer el portafolio profesional.', 'Objetivo General: Capacitar en el diseño, desarrollo, evaluación de impacto y despliegue de sistemas de IA Generativa empresariales utilizando arquitecturas RAG para optimizar la toma de decisiones, garantizando el despliegue funcional en entornos de nube y repositorios públicos orientados a portafolios profesionales.
Objetivo Específico 1: Evaluar casos de uso de negocio y modelos de orquestación cognitiva (LangChain / LlamaIndex) para resolver ineficiencias operativas con métricas claras de viabilidad técnica y financiera.
Objetivo Específico 2: Implementar bases de datos vectoriales para el almacenamiento y recuperación de embeddings semánticos con enfoque en seguridad y eficiencia.
Objetivo Específico 3: Desplegar un Proyecto Integrador de negocio en un servicio de nube pública (AWS o Azure) con código fuente versionado en GitHub para su demostración en portafolios profesionales.', 'Científicos de datos, tecnólogos en análisis de datos, ingenieros de desarrollo de software, analistas de BI senior, consultores de innovación y líderes técnicos con conocimientos en programación con Python interesados en aplicar IA con impacto real en los negocios.', 'Enfoque 100% práctico (''learning-by-doing'') orientado a la resolución de retos de negocio. A lo largo del programa, los participantes desarrollan un Proyecto Integrador de IA Generativa basado en una necesidad empresarial real. Las sesiones combinan teoría aplicada, laboratorios en Google Colab con APIs comerciales y modelos open-source, y mentorías dedicadas al versionamiento de código en GitHub y el despliegue continuo en la nube (AWS/Azure). El programa finaliza con un Demo Day donde los estudiantes presentan sus productos desplegados en producción y sus repositorios públicos.', 'Proyecto Final integrador real desplegado en infraestructura Cloud (AWS/Azure) listo para incluir en el perfil profesional.
Repositorio funcional en GitHub estructurado bajo estándares de la industria, optimizado como evidencia técnica.
Inclusión en el portafolio institucional de microcredenciales digitales insignias de UniCafam con estándar internacional OpenBadges.
Acceso a la comunidad de expertos en Inteligencia Artificial y Transformación Digital de la Escuela de Ingeniería de UniCafam.
Plantillas de código y arquitectura orientadas a producción empresarial con estimación de costos operacionales.', 'Profesional o estudiante con conocimientos fundamentales de programación en Python, comprensión conceptual de bases de datos y orientación al desarrollo de soluciones de datos empresariales.', 'El egresado identificará y evaluará casos de negocio para IA Generativa, construirá pipelines de RAG avanzado sobre información corporativa no estructurada, indexará vectores en bases de datos en la nube, orquestará agentes inteligentes y desplegará soluciones completas en AWS o Azure con control de versiones en GitHub para exhibir en entornos laborales.', 'Machine Learning / AI Engineer (18.2% de ofertas en el observatorio, corte 2026-10-28), Científico de Datos (Data Scientist) (31.2% de ofertas en el observatorio, corte 2026-10-28), Desarrollador de Aplicaciones de IA / Software (0.5% de ofertas en el observatorio, corte 2026-10-28)', 'En el mercado local (Colombia - COP), la mediana salarial general observada es de $4.478.000 COP/mes (n=133 ofertas con salario publicado, corte 2026-10-28). Dato no disponible: el observatorio no tiene una prima salarial concluyente aprobada para el rol de Machine Learning / AI Engineer (resultado ''No'', n=39) ni para la habilidad de NLP / LLMs (corte 2026-10-28). En el mercado internacional remoto (USD), la mediana salarial es de $14.600.000 COP/mes (n=11 ofertas con salario publicado, muestra pequeña).', 'https://jfbernalp.dev/downloads/mig/PROP_02_MIG.xlsx', 'PENDIENTE_REVISION', 3, '', '2026-10-28 01:42:38', '');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 1, 'Sistema Observatorio IA UniCafam', 'Motor Generativo (Gemini 3.5 Flash)', 'CREACION_INICIAL', 'Generación curricular inicial groundeada en datos del mercado laboral y Decreto 1330 MEN.', 'Diseño base de microcurrículos, RAEs y perfil docente.', '2026-10-03 12:00:00');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 1, 'Decanatura / Comité Curricular UniCafam', 'Usuario Aprobador', 'APROBADO', 'Aprobación formal otorgada por Decanatura / Comité Curricular UniCafam (Usuario Aprobador). Propuesta habilitada para despliegue público y radicación oficial MIG.', 'Cambio de estado formal en el flujo de aprobación.', '2026-10-24 08:54:01');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 1, 'Decanatura / Comité Curricular UniCafam', 'Usuario Aprobador', 'REAPERTURA_REVISION', 'Propuesta reabierta para nueva deliberación o ajustes curriculares.', 'Estado retornado a PENDIENTE_REVISION.', '2026-10-24 08:54:22');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 2, 'Decanatura / Comité Curricular UniCafam', 'Usuario Aprobador', 'SOLICITUD_AJUSTE', 'El enfoque de negocios no se ve claramente, se debe incluir siempre un proyecto fianl que el estudiante debe tener desplegado en github y un servicio de nube como aws o azure para mostrar en entrevistas de trabajo', 'Se acató estrictamente la retroalimentación de la Decanatura y Comité Curricular: 1) Se fortaleció transversalmente el enfoque de negocios, incorporando la evaluación de ROI, estimación de costos de token e impacto corporativo en la justificación, objetivos, perfil de egreso y microcurrículo. 2) Se incluyó explícitamente la obligatoriedad de un Proyecto Final Integrador que los estudiantes deben publicar en un repositorio estructurado de GitHub y desplegar en una plataforma de nube (AWS o Azure), garantizando un producto demostrable en entrevistas de trabajo y portafolios profesionales. 3) Se actualizaron los RAEs y el stack tecnológico para reflejar la inclusión de GitHub, AWS y Azure manteniendo el rigor conceptual y las proporciones horarias normativas (2 créditos = 96 horas totales: 32 TFD / 64 TTI).', '2026-10-24 08:56:23');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 2, 'Decanatura / Comité Curricular UniCafam', 'Usuario Aprobador', 'APROBADO', 'Aprobación formal otorgada por Decanatura / Comité Curricular UniCafam (Usuario Aprobador). Propuesta habilitada para despliegue público y radicación oficial MIG.', 'Cambio de estado formal en el flujo de aprobación.', '2026-10-24 08:59:15');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 2, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'REAPERTURA_REVISION', 'Propuesta reabierta para nueva deliberación o ajustes curriculares.', 'Estado retornado a PENDIENTE_REVISION.', '2026-10-28 01:42:09');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_02', 3, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'SOLICITUD_AJUSTE', 'Regeneración institucional con el contexto de mercado verificado del observatorio. Mantenga el tipo de programa, su nivel, créditos y horas. Revise el enfoque y los módulos a la luz de la demanda de habilidades y de los roles del contexto, y reemplace TODAS las cifras de mercado por cifras del contexto (con su n y el corte) o por ''Dato no disponible en el observatorio''. Tarifas: ''Por definir según tarifario institucional''.', 'Se reajustó completamente la propuesta bajo la estricta alineación con los datos del Observatorio de Empleo UniCafam (corte 2026-10-28, n=570 ofertas). Se reemplazaron todas las cifras no fundamentadas de salarios, incrementos porcentuales arbitrarios (+40%) y promedios no documentados por las cifras oficiales del contexto con su respectivo ''n''. La sección de inversión fue actualizada a ''Por definir según tarifario institucional''. Se reorientaron los roles objetivo (Machine Learning / AI Engineer, Científico de Datos) acorde con los perfiles del observatorio y sus demandas de habilidades (Python 56.7%, SQL 62.3%, Azure 24.0%, AWS 23.5%, NLP/LLMs 6.1%, Git 14.6%). Se mantuvo la estructura crediticia de 2 créditos (32 TFD, 64 TTI, 96 totales) acorde al Decreto 1330 MEN.', '2026-10-28 01:42:38');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_02', 1, 'Arquitecturas RAG & Bases de Datos Vectoriales para Soluciones de Negocio', '1', 2, 32, 64, 96, '1. Estrategia de IA Generativa en Negocios: Casos de uso, estimación de viabilidad, latencia y costos de inferencia por token.
2. Fundamentos de Embeddings & Búsqueda Semántica aplicados a repositorios documentales corporativos.
3. Bases de Datos Vectoriales (Pinecone, ChromaDB, Qdrant): Gestión, indexación y seguridad de datos empresariales.
4. Flujo RAG (Retrieval-Augmented Generation) Avanzado: Chunking estratégico, re-ranking y mitigación de alucinaciones.
5. Frameworks de Orquestación: Construcción paso a paso de flujos cognitivos con LangChain y LlamaIndex.
6. Agentes Autónomos y Tool Use: Integración con APIs corporativas y bases de datos SQL para analítica conversacional.
7. Versionamiento Profesional con Git/GitHub: Estructuración de proyectos y documentación de código.
8. Proyecto Final Integrador & Despliegue Cloud: Empaquetamiento de la aplicación y despliegue en servicios de nube (AWS o Azure) para portafolio laboral.', 'Semanas 1 a 8', 'Python, SQL, LangChain, LlamaIndex, Pinecone, ChromaDB, OpenAI API / Claude, Git / GitHub, AWS, Azure, Streamlit / FastAPI', 'Evaluar arquitecturas de Inteligencia Artificial Generativa y RAG según la relación costo-beneficio e impacto en la eficiencia de los procesos de negocio. | Construir sistemas de persistencia e indexación vectorial optimizados garantizando la seguridad de la información y la precisión semántica. | Desplegar aplicaciones de IA Generativa en infraestructura de nube (AWS o Azure) utilizando control de versiones con Git/GitHub como evidencia demostrable para el entorno laboral.', 'Según el Observatorio de Empleo UniCafam (corte 2026-10-28, n=570), Python está presente en el 56.7% de las ofertas, SQL en el 62.3%, Azure en el 24.0%, AWS en el 23.5%, Git / Control de Versiones en el 14.6% y NLP / LLMs en el 6.1%. Estas competencias responden a la demanda de perfiles en Machine Learning / AI Engineer (18.2% de los roles) y Científico de Datos (31.2%).');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_02', 'Investigador / Ingeniero Senior en NLP & IA Generativa para Negocios', 'Arquitecturas RAG & Bases de Datos Vectoriales para Soluciones de Negocio', 'Profesional en Ingeniería de Sistemas, Inteligencia Artificial o Ciencia de Datos, con Posgrado o experiencia equivalente en IA y Ciencias de la Computación, con más de 3 años de experiencia liderando proyectos de IA Generativa en la industria, despliegue en entornos Cloud (AWS/Azure) y desarrollo de soluciones de datos.');
INSERT INTO dim_propuestas_curriculares_mig VALUES ('PROP_03', 'Especialización Universitaria', 'Especialización en Ingeniería de Datos y Arquitecturas Cloud', 'Especialista en Ingeniería de Datos y Arquitecturas Cloud', 'Posgrado', '2 semestres', 24, 1152, 'Híbrida (Virtual interactiva con laboratorios prácticos sincrónicos de alta intensidad)', 'Viernes de 5:00 p.m. a 10:00 p.m. y Sábados de 8:00 a.m. a 2:00 p.m.', 'Julio de 2025', 'Junio de 2026', 'Admisiones anuales para inicio en cada periodo académico del segundo semestre', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'La ingeniería de datos es un pilar fundamental en el ecosistema analítico moderno. Según datos del Observatorio de Empleo UniCafam (corte 2026-10-28), el rol de Ingeniero de Datos (Data Engineer) abarca 146 ofertas laborales (25.6% del total analizado de 570 ofertas). Las principales habilidades demandadas para este rol son ETL / Pipelines de Datos (presente en el 82.9% de sus ofertas y en el 45.4% del total general con 259 ofertas), SQL (78.8% en el rol y 62.3% total), Python (62.3% en el rol y 56.7% total), plataformas en la nube como AWS (44.5% en el rol, 23.5% total) y Azure (36.3% en el rol, 24.0% total), así como Spark / PySpark (36.3% en el rol, 18.6% total) y Databricks (33.6% en el rol, 16.8% total). El programa forma a los estudiantes en el diseño e implementación de arquitecturas de almacenamiento, orquestación y procesamiento masivo de datos para satisfacer la demanda empresarial.', 'Objetivo General: Formar especialistas capaces de estructurar, optimizar y liderar la arquitectura de almacenamiento, procesamiento y distribución de flujos de datos empresariales multi-nube bajo estándares de seguridad y alta disponibilidad.
Objetivo Específico 1: Configurar sistemas distribuidos e infraestructuras híbridas para el procesamiento de datos estructurados y no estructurados con alta eficiencia.
Objetivo Específico 2: Diseñar flujos de integración y orquestación de datos automatizados con tolerancia a fallas utilizando herramientas líderes en la industria como Apache Airflow y servicios en la nube.
Objetivo Específico 3: Implementar arquitecturas modernas de almacenamiento analítico como Lakehouses, Databricks y soluciones distribuidas.', 'Egresados de pregrados profesionales en ingeniería de sistemas, ingeniería de software, ciencia de datos o tecnólogos con experiencia profesional comprobada en programación y bases de datos relacionales.', 'La metodología pedagógica integra estudios de casos reales con prácticas de co-diseño de arquitectura empresarial en la nube. Los laboratorios se desarrollan utilizando arquitecturas multi-cloud. Cada módulo de posgrado requiere la resolución de un problema de rendimiento de Big Data empresarial, evaluando tanto la eficiencia técnica como la optimización de recursos en la nube.', 'Alineación práctica con las competencias exigidas para certificaciones de la industria en soluciones Cloud y Big Data.
Acceso al Laboratorio de Ciberseguridad y Big Data de la Escuela de Ingeniería de UniCafam.
Cátedra abierta de casos de éxito dictada por expertos y líderes de datos de la región.', 'Profesional graduado en ingeniería de sistemas, analítica, ciencia de datos u otras ramas de la ingeniería de software, con conocimientos prácticos en lenguajes de programación como Python y bases de datos transaccionales.', 'El Especialista de UniCafam podrá modelar y desplegar almacenes de datos masivos en la nube, crear y gestionar canalizaciones de datos distribuidas con Spark y Apache Airflow, coordinar esquemas de gobernanza, seguridad y monitoreo de la calidad de datos, y liderar técnicamente la infraestructura analítica corporativa.', 'Ingeniero de Datos (Data Engineer), Arquitecto de Datos Cloud, Administrador de Infraestructuras Analíticas', 'Dato no disponible: el observatorio no tiene una prima concluyente para el rol de Ingeniero de Datos (Data Engineer) por limitación de muestra (n = 11, n < 20, corte 2026-10-28). La mediana salarial general registrada para el mercado local en Colombia es de $4.478.000 COP (n_con_salario = 133, corte 2026-10-28) y para el mercado internacional remoto es de $14.600.000 COP (n_con_salario = 11, corte 2026-10-28).', 'https://jfbernalp.dev/downloads/mig/PROP_03_MIG.xlsx', 'PENDIENTE_REVISION', 2, '', '2026-10-28 01:42:57', '');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_03', 1, 'Sistema Observatorio IA UniCafam', 'Motor Generativo (Gemini 3.5 Flash)', 'CREACION_INICIAL', 'Generación curricular inicial groundeada en datos del mercado laboral y Decreto 1330 MEN.', 'Diseño base de microcurrículos, RAEs y perfil docente.', '2026-10-03 12:00:00');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_03', 1, 'Ing. María Fernanda Rojas', 'Directora de Programa Ciencia de Datos', 'APROBADO', 'Aprobación formal otorgada por Ing. María Fernanda Rojas (Directora de Programa Ciencia de Datos). Propuesta habilitada para despliegue público y radicación oficial MIG.', 'Cambio de estado formal en el flujo de aprobación.', '2026-10-16 17:34:04');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_03', 1, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'REAPERTURA_REVISION', 'Propuesta reabierta para nueva deliberación o ajustes curriculares.', 'Estado retornado a PENDIENTE_REVISION.', '2026-10-28 01:42:38');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_03', 2, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'SOLICITUD_AJUSTE', 'Regeneración institucional con el contexto de mercado verificado del observatorio. Mantenga el tipo de programa, su nivel, créditos y horas. Revise el enfoque y los módulos a la luz de la demanda de habilidades y de los roles del contexto, y reemplace TODAS las cifras de mercado por cifras del contexto (con su n y el corte) o por ''Dato no disponible en el observatorio''. Tarifas: ''Por definir según tarifario institucional''.', 'Se actualizó la totalidad de la propuesta con el contexto de mercado del Observatorio UniCafam (corte 2026-10-28). Se eliminaron afirmaciones y cifras de salarios sin respaldo o extrapolares; la sección de impacto salarial se ajustó a ''Dato no disponible'' especificando la falta de prima concluyente (n=11, n<20) y reportando las medianas del contexto. Se reajustaron los precios de inversión a ''Por definir según tarifario institucional''. Se actualizaron los datos de demanda laboral por porcentaje y conteo de ofertas reales por habilidad y rol. Se mantuvieron la estructura de créditos (24 créditos total) y el cálculo de horas conforme a la reglamentación.', '2026-10-28 01:42:57');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_03', 1, 'Procesamiento Distribuido a Gran Escala con Databricks & Spark', '1', 4, 64, 128, 192, '1. Fundamentos de computación distribuida y arquitecturas de memoria.
2. Arquitectura interna de Apache Spark y APIs principales (DataFrames y SQL).
3. Gestión de clústeres de datos, procesamiento Batch y Streaming de datos.
4. Introducción a la plataforma unificada Databricks.
5. El paradigma Lakehouse y persistencia tolerante a fallas con Delta Lake.
6. Optimización de rendimiento de procesamiento distribuido y particionamiento de datos.', 'Semanas 1 a 12 (Primer Semestre)', 'Apache Spark, PySpark, Databricks, Delta Lake, SQL', 'Estructurar flujos de datos analíticos masivos procesando información de forma paralela en clústeres de cómputo en la nube. | Diseñar estructuras de almacenamiento Lakehouse que permitan la ingesta y consulta de datos con esquemas de consistencia ACID.', 'Según el Observatorio de Empleo UniCafam (corte 2026-10-28), Spark / PySpark está presente en 106 ofertas (18.6% del total) y en el 36.3% de las ofertas para Ingenieros de Datos. Por su parte, Databricks aparece en 96 ofertas (16.8% del total) y en el 33.6% de las ofertas del rol.');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_03', 2, 'Orquestación de Pipelines & Cloud Integration', '1', 4, 64, 128, 192, '1. Flujos lógicos e interdependencia de procesos de datos.
2. Concepto de DAG (Directed Acyclic Graphs) y automatización.
3. Implementación de orquestadores industriales con Apache Airflow.
4. Integración y despliegue de canalizaciones de datos en AWS y Azure.
5. Monitoreo automatizado, alertas y control de fallas en producción.
6. Gobierno, linaje y procedencia de datos en pipelines corporativos.', 'Semanas 13 a 24 (Primer Semestre)', 'Apache Airflow, AWS, Azure, Python, SQL', 'Diseñar flujos de procesamiento automatizados y orquestados que incluyan mecanismos de tolerancia a fallas y alertas preventivas. | Implementar esquemas de integración de datos en la nube garantizando la trazabilidad y calidad de la información.', 'ETL / Pipelines de Datos es la habilidad más requerida para Ingenieros de Datos con un 82.9% de penetración en el rol (259 ofertas totales, 45.4%). AWS y Azure están presentes en el 44.5% y 36.3% de las ofertas del rol respectivamente, mientras que Airflow registra 53 ofertas (9.3% total) a corte 2026-10-28.');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_03', 3, 'Infraestructura como Código, Docker & Kubernetes para Datos', '2', 4, 64, 128, 192, '1. Contenedores y virtualización en entornos de ingeniería de datos.
2. Creación y gestión de servicios multi-contenedor con Docker.
3. Fundamentos de orquestación a escala con Kubernetes.
4. Despliegue de bases de datos y herramientas analíticas en clústeres.
5. Infraestructura como Código (IaC) para aprovisionamiento automatizado.
6. Prácticas de seguridad en redes de datos de alta disponibilidad.', 'Semanas 1 a 12 (Segundo Semestre)', 'Docker, Kubernetes, Terraform, YAML', 'Desplegar entornos de infraestructura reproductibles mediante código para el soporte de servicios de procesamiento de datos. | Orquestar aplicaciones analíticas garantizando la escalabilidad y disponibilidad de los recursos informáticos.', 'Docker / Kubernetes cuenta con 29 ofertas (5.1% del total) a corte 2026-10-28, constituyendo una competencia técnica complementaria para la automatización y despliegue de infraestructura analítica.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_03', 'Especialista de Infraestructuras Big Data y Spark', 'Procesamiento Distribuido a Gran Escala con Databricks & Spark', 'Ingeniero de Datos o de Sistemas con posgrado/maestría en área afín, con experiencia en diseño de sistemas distribuidos y plataformas como Databricks y Spark.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_03', 'Arquitecto Senior de Integraciones Cloud', 'Orquestación de Pipelines & Cloud Integration', 'Magíster en Ingeniería de Sistemas o Ciencias de la Computación, con experiencia en orquestación de datos corporativos, Apache Airflow y servicios Cloud (AWS/Azure).');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_03', 'Especialista en DevOps e Infraestructura como Código (IaC)', 'Infraestructura como Código, Docker & Kubernetes para Datos', 'Ingeniero de Software o Sistemas especialista en DevOps/Cloud Infrastructure, con experiencia en despliegue de contenedores con Docker, Kubernetes y Terraform.');
INSERT INTO dim_propuestas_curriculares_mig VALUES ('PROP_04', 'Maestría Aplicada', 'Maestría en Inteligencia Artificial y Ciencia de Datos Estratégica', 'Magíster en Inteligencia Artificial y Ciencia de Datos Estratégica', 'Posgrado / Maestría', '4 semestres', 48, 2304, 'Híbrida de alta flexibilidad', 'Jornada Nocturna y Concentrada en Fines de Semana (Híbrida)', 'Agosto de 2025', 'Junio de 2027', 'Apertura anual para cada segundo semestre académico', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Según datos del Observatorio de Empleo UniCafam (corte del 2026-10-28, n = 570 ofertas), el rol de Científico de Datos lidera la demanda en el mercado de analítica avanzada con el 31.2% de las ofertas (178 ofertas), seguido por el rol de Machine Learning / AI Engineer con el 18.2% (104 ofertas). A nivel de habilidades requeridas, Python está presente en el 56.7% de las ofertas (323 ofertas), SQL en el 62.3% (355 ofertas), ETL / Pipelines de Datos en el 45.4% (259 ofertas) y Machine Learning General en el 27.5% (157 ofertas). Habilidades especializadas como Deep Learning (4.0%, 23 ofertas), PyTorch (4.2%, 24 ofertas) y TensorFlow / Keras (4.4%, 25 ofertas) complementan las arquitecturas complejas requeridas por las organizaciones. Esta maestría aplicada aborda las brechas técnicas de alto nivel alineando el desarrollo analítico con las exigencias directivas e infraestructurales del mercado local e internacional.', 'Objetivo General: Formar magísteres con competencias de liderazgo técnico para diseñar, implementar y gestionar soluciones integrales de Inteligencia Artificial y Aprendizaje Automático orientadas a generar valor estratégico en las organizaciones.
Objetivo Específico 1: Diseñar arquitecturas de aprendizaje profundo utilizando Python, PyTorch y frameworks avanzados para el procesamiento de datos estructurados y no estructurados.
Objetivo Específico 2: Estructurar estrategias de modelamiento decisional y analítica avanzada integrando metodologías de datos para resolver problemas complejos de negocio.
Objetivo Específico 3: Implementar esquemas de gobernanza de datos y principios de IA explicable (XAI) asegurando el cumplimiento normativo, la transparencia y la equidad algorítmica.', 'Profesionales y directores en áreas de Ciencia de Datos, Ingeniería de Sistemas, Estadística, Matemáticas o afines, con experiencia cuantitativa que busquen asumir roles de liderazgo técnico e ingeniería analítica avanzada.', 'Seminarios aplicados integrados con laboratorios computacionales prácticos. El programa se centra en el desarrollo de un Proyecto de Grado de Aplicación Industrial orientado a resolver problemas analíticos reales de alto impacto técnico y organizacional.', 'Formación rigurosa alineada con las habilidades de mayor demanda del mercado: Python (56.7% de ofertas) y SQL (62.3% de ofertas) según corte 2026-10-28 (n = 570).
Integración de pipelines de datos (ETL) y marcos de gobernanza algorítmica aplicados a la toma de decisiones empresariales.
Posibilidad de articulación y homologación de créditos para egresados de posgrados de la Escuela de Ingeniería de UniCafam conforme a normativa institucional.', 'Profesionales en Ingeniería, Ciencia de Datos, Ciencias Básicas o áreas afines, con bases sólidas en programación (preferiblemente Python), gestión de bases de datos relacionales (SQL) y fundamentos de modelamiento matemático y predictivo.', 'El egresado estará capacitado para liderar equipos de ciencia de datos y aprendizaje automático, diseñar arquitecturas de aprendizaje profundo, implantar modelos explicables (XAI) y establecer marcos de gobernanza de datos orientados al cumplimiento normativo corporativo.', 'Científico de Datos (Data Scientist) - 31.2% de demanda en el observatorio (178 ofertas, corte 2026-10-28), Machine Learning / AI Engineer - 18.2% de demanda en el observatorio (104 ofertas, corte 2026-10-28), Líder / Director de Ciencia de Datos e Inteligencia Artificial', 'En el mercado local (Colombia - COP), la mediana salarial reportada para ofertas con salario publicado es de $4.478.000 COP (n = 133 de 542 ofertas totales, corte 2026-10-28). En el mercado internacional remoto, la mediana salarial es de $14.600.000 COP (n = 11 con salario publicado de 28 ofertas totales). En cuanto a primas salariales por rol concluyentes con controles, el rol de Analista de Datos presenta una penalización de -32.7% (IC 95%: -42.0% a -22.0%, q_bh = 0.0) frente al rol de referencia Científico de Datos (0.0%, n = 60). Para otros roles las primas no son concluyentes en la muestra.', 'https://jfbernalp.dev/downloads/mig/PROP_04_MIG.xlsx', 'PENDIENTE_REVISION', 2, '', '2026-10-28 01:43:44', '');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_04', 1, 'Sistema Observatorio IA UniCafam', 'Motor Generativo (Gemini 3.5 Flash)', 'CREACION_INICIAL', 'Generación curricular inicial groundeada en datos del mercado laboral y Decreto 1330 MEN.', 'Diseño base de microcurrículos, RAEs y perfil docente.', '2026-10-03 12:00:00');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_04', 2, 'Observatorio UniCafam', 'Regeneración con contexto verificado', 'SOLICITUD_AJUSTE', 'Regeneración institucional con el contexto de mercado verificado del observatorio. Mantenga el tipo de programa, su nivel, créditos y horas. Revise el enfoque y los módulos a la luz de la demanda de habilidades y de los roles del contexto, y reemplace TODAS las cifras de mercado por cifras del contexto (con su n y el corte) o por ''Dato no disponible en el observatorio''. Tarifas: ''Por definir según tarifario institucional''.', 'Se actualizó la propuesta al corte del 2026-10-28 del Observatorio de Empleo UniCafam (n = 570 ofertas). Se ajustaron todas las cifras de mercado eliminando estimaciones o afirmaciones sin respaldo: se incluyeron la participación de roles (Científico de Datos 31.2%, Machine Learning / AI Engineer 18.2%) y habilidades (SQL 62.3%, Python 56.7%, ETL 45.4%, Machine Learning 27.5%, etc.) con sus n correspondientes. Se actualizó el impacto salarial citando las medianas locales ($4.478.000 COP, n = 133) e internacionales ($14.600.000 COP, n = 11), así como la prima concluyente por rol (Analista de Datos -32.7% vs Científico de Datos). La sección de inversión se unificó a ''Por definir según tarifario institucional''. Se recalcularon explícitamente las horas de los módulos según la fórmula del Decreto 1330 (4 créditos = 64 TFD, 128 TTI, 192 totales) y se redactaron los RAEs con verbos observables de la Taxonomía de Bloom.', '2026-10-28 01:43:44');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_04', 1, 'Modelado Avanzado de Aprendizaje Profundo & Redes Neuronales', '1', 4, 64, 128, 192, '1. Fundamentos de aprendizaje profundo y retropropagación.
2. Arquitecturas convolucionales para visión por computador.
3. Redes recurrentes y procesamiento de secuencias temporales.
4. Mecanismos de atención y arquitecturas basadas en Transformers.
5. Ajuste fino de modelos y optimización de cómputo en PyTorch y TensorFlow.', 'Semanas 1 a 12 (Primer Semestre)', 'Python, PyTorch, TensorFlow, Keras, Hugging Face', 'Construir modelos de aprendizaje profundo utilizando Python y PyTorch para resolver problemas complejos de clasificación y regresión sobre datos estructurados y no estructurados. | Evaluar el rendimiento de arquitecturas basadas en Transformers mediante métricas estandarizadas de rendimiento computacional y precisión.', 'Python es requerido en el 56.7% de las ofertas del mercado (323 ofertas). Habilidades como Machine Learning General (27.5%, 157 ofertas), PyTorch (4.2%, 24 ofertas) y TensorFlow / Keras (4.4%, 25 ofertas) sustentan técnicamente el perfil de Machine Learning / AI Engineer (18.2% de demanda) y Científico de Datos (31.2% de demanda).');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_04', 2, 'Inferencia Causal & Modelamiento Decisional para Negocios', '2', 4, 64, 128, 192, '1. Principios de causalidad vs. correlación en ciencia de datos.
2. Grafos dirigidos acíclicos y marcos causales.
3. Diseño de experimentos y pruebas A/B a escala organizacional.
4. Métodos cuasi-experimentales: variables instrumentales, diferencias en diferencias y pareamiento por puntaje de propensión.
5. Modelado analítico orientado al soporte de decisiones estratégicas.', 'Semanas 1 a 12 (Segundo Semestre)', 'Python, SQL, DoWhy, CausalML, Statsmodels', 'Formular modelos de inferencia causal aplicados a datos de negocio para diferenciar efectos directos de simples correlaciones en la toma de decisiones. | Diseñar esquemas de experimentación A/B analizando resultados mediante herramientas cuantitativas para respaldar decisiones estratégicas.', 'El modelamiento estadístico es demandado en el 30.9% de las ofertas (176 ofertas) y SQL en el 62.3% (355 ofertas). El rol de Científico de Datos (31.2% de las ofertas) requiere una combinación sólida de habilidades de modelamiento y análisis SQL.');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_04', 3, 'Gobernanza de Datos, Ética en IA & Algoritmos Explicables (XAI)', '3', 4, 64, 128, 192, '1. Identificación y mitigación de sesgos en modelos de aprendizaje automático.
2. Térmicas de explicabilidad de caja negra: SHAP y LIME.
3. Principios de gobernanza de datos y cumplimiento ético-normativo.
4. Auditoría algorítmica y gestión del riesgo en la adopción de soluciones de IA.
5. Arquitectura de procesos de datos transparentes e integrados con pipelines corporativos.', 'Semanas 1 a 12 (Tercer Semestre)', 'Python, SHAP, LIME, Fairlearn, InterpretML', 'Aplicar técnicas de explicabilidad (SHAP, LIME) sobre modelos predictivos complejos para auditar y justificar sus decisiones ante grupos de interés corporativos. | Diseñar marcos de gobernanza de datos que aseguren el cumplimiento de normativas de transparencia y la reducción de sesgos en sistemas de inteligencia artificial.', 'Integrar pipelines de datos (ETL presente en el 45.4% de ofertas) con gobernanza técnica y explicabilidad permite a las empresas desplegar IA de manera confiable, respondiendo a las necesidades operativas de los roles de Científico de Datos e Ingeniero de Datos.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_04', 'Experto en Aprendizaje Profundo y Ciencias de la Computación', 'Modelado Avanzado de Aprendizaje Profundo & Redes Neuronales', 'Doctor o Magíster en Ciencias de la Computación, IA o afines, con experiencia acreditada en desarrollo e implementación de modelos de redes neuronales profundas con Python, PyTorch y TensorFlow en entornos productivos.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_04', 'Especialista en Modelamiento Cuantitativo e Inferencia Causal', 'Inferencia Causal & Modelamiento Decisional para Negocios', 'Doctor o Magíster en Estadística, Economía Cuantitativa o Ciencia de Datos, con trayectoria en diseño experimental, econometría aplicada e inferencia causal para soporte decisional.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_04', 'Experto en Gobernanza de Datos y Explicabilidad Algorítmica (XAI)', 'Gobernanza de Datos, Ética en IA & Algoritmos Explicables (XAI)', 'Magíster o Doctor en Ciencia de Datos, Sistemas de Información o Derecho Digital / Ética Tecnológica, con experiencia en auditoría algorítmica, implementación de SHAP/LIME y normativas de datos.');
INSERT INTO dim_propuestas_curriculares_mig VALUES ('PROP_05', 'Diplomado', 'Diplomado en Arquitecturas de Datos en la Nube y Procesos ETL Avanzados (Opción de Grado)', 'Diplomado en Arquitecturas de Datos en la Nube y Procesos ETL Avanzados', 'Pregrado', '1 semestre (Opción de Grado - 720 horas totales)', 15, 720, 'Híbrida / PAT (Presencial Asistida por Tecnología)', 'Viernes de 6:00 p.m. a 10:00 p.m. y Sábados de 7:00 a.m. a 1:00 p.m. / Sesiones sincrónicas y laboratorios asistidos', 'Próximo inicio de cohorte académica', 'Al completar el número total de horas (720 horas / 15 créditos)', 'Cohortes semestrales continuas (Opción de Grado Pregrado)', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Por definir según tarifario institucional', 'Este diplomado de 15 créditos académicos (720 horas totales: 240 horas TFD y 480 horas TTI, conforme al Decreto 1330) se estructura como opción de grado de pregrado para fortalecer las competencias de los estudiantes de UniCafam en arquitecturas en la nube y procesos ETL, articulando las fortalezas consolidadas del currículo actual con las brechas de mayor demanda en el Observatorio de Empleo UniCafam (corte 2026-10-28, n = 570 ofertas). En primer lugar, ETL / Pipelines de Datos es la tercera habilidad más demandada del mercado general con el 45.4 % (n = 259 de 570 ofertas), precedida únicamente por SQL con el 62.3 % (n = 355) y Python con el 56.7 % (n = 323). Si bien UniCafam ya enseña SQL, Python, ETL y Spark / PySpark (18.6 %, n = 106 de 570 ofertas), las cuatro principales brechas curriculares no cubiertas pertenecen a la categoría Big Data & Cloud: Azure en el 24.0 % de las ofertas (n = 137 de 570), AWS en el 23.5 % (n = 134), Google Cloud (GCP) en el 19.1 % (n = 109) y Databricks en el 16.8 % (n = 96), seguidas en el área de Data Engineering & Ops por Airflow en el 9.3 % (n = 53), MLOps en el 7.4 % (n = 42) y Docker / Kubernetes en el 5.1 % (n = 29). En segundo lugar, el diseño curricular responde directamente a los tres roles con mayor participación en el mercado (corte 2026-10-28): (1) Científico de Datos (Data Scientist), que concentra el 31.2 % de las vacantes (n = 178 de 570 ofertas) y requiere Python (56.7 %), SQL (51.1 %), Machine Learning General (42.1 %), Estadística / Modelamiento (37.6 %), ETL / Pipelines de Datos (34.3 %), Azure (24.7 %) y AWS (19.7 %); (2) Ingeniero de Datos (Data Engineer), con el 25.6 % de las vacantes (n = 146 de 570 ofertas), donde ETL / Pipelines de Datos alcanza el 82.9 % de las ofertas del rol, junto con SQL (78.8 %), Python (62.3 %), AWS (44.5 %), Azure (36.3 %), Spark / PySpark (36.3 %), Databricks (33.6 %) y Google Cloud (GCP) (28.8 %); y (3) Machine Learning / AI Engineer, con el 18.2 % (n = 104 de 570 ofertas), que exige Python (56.7 %), SQL (46.2 %), Machine Learning General (37.5 %), ETL / Pipelines de Datos (32.7 %), AWS (19.2 %) y Azure (19.2 %). Adicionalmente, en términos salariales, el rol de Analista de Datos (Data Analyst) (16.8 %, n = 96 de 570 ofertas) registra una prima salarial concluyente de -32.7 % (IC 95 %: -42.0 % a -22.0 %, q_bh = 0.0, n = 41 ofertas con salario) frente al rol de referencia Científico de Datos (n = 60 ofertas con salario), por lo que habilitar el tránsito de los estudiantes hacia roles de Ingeniería de Datos y Ciencia de Datos mediante el dominio de arquitecturas cloud y ETL avanzado resulta estratégico para la competitividad de los futuros graduados de la Escuela de Ingeniería.', 'Objetivo General: Desarrollar en los estudiantes de pregrado de UniCafam, bajo la modalidad de opción de grado, competencias aplicadas para diseñar, construir y orquestar arquitecturas de datos en la nube y procesos ETL de nivel industrial, integrando sus bases previas en SQL, Python y Spark con los ecosistemas AWS, Azure, Google Cloud (GCP), Databricks y Airflow.
Objetivo Específico 1: Implementar pipelines de extracción, transformación y carga (ETL/ELT) y bodegas de datos en AWS y Google Cloud (GCP), articulando almacenamiento distribuido y procesamiento serverless.
Objetivo Específico 2: Construir arquitecturas Lakehouse y flujos de procesamiento distribuido sobre Microsoft Azure y Databricks utilizando Spark / PySpark y SQL.
Objetivo Específico 3: Automatizar y desplegar canalizaciones de datos e infraestructura reproducible mediante Apache Airflow, contenedores Docker / Kubernetes y prácticas de MLOps orientadas al consumo analítico.', 'Estudiantes de últimos semestres de los programas de pregrado de UniCafam (Tecnología en Análisis y Gestión de Datos, Profesional en Ciencia de Datos e Ingeniería de Sistemas) que cursen su opción de grado y cuenten con bases previas en SQL, Python, bases de datos y fundamentos de ETL.', 'Metodología teórico-práctica basada en Aprendizaje Basado en Proyectos (ABP / PBL) bajo lineamientos de la Matriz Integrada de Gestión (MIG) y el Decreto 1330. Las 240 horas de Trabajo con Acompañamiento Directo del Docente (TFD) se desarrollan en talleres guiados de arquitectura cloud e ingeniería de datos, mientras que las 480 horas de Trabajo Independiente (TTI) se enfocan en la implementación progresiva de un proyecto integrador de extremo a extremo (End-to-End Cloud Data Pipeline) versionado en GitHub.', 'Opción de grado de 15 créditos (720 horas) diseñada sobre la evidencia empírica del Observatorio de Empleo UniCafam (corte 2026-10-28, n = 570 ofertas).
Cierre directo de las cuatro mayores brechas tecnológicas del currículo: Azure (24.0 %), AWS (23.5 %), Google Cloud (GCP) (19.1 %) y Databricks (16.8 %), potenciando la fortaleza en ETL / Pipelines de Datos (45.4 %).
Preparación integral alineada con el perfil técnico del rol de Ingeniero de Datos (25.6 % de las ofertas) y Científico de Datos (31.2 % de las ofertas).', 'Estudiante de pregrado con conocimientos consolidados en programación en Python (Pandas, scripting), consultas en SQL relacional y NoSQL, control de versiones con Git/GitHub, estadística descriptiva/predictiva y visualización en Power BI o Tableau, adquiridos en los microcurrículos de UniCafam.', 'El graduado del diplomado estará en capacidad de diseñar, aprovisionar, orquestar y gobernar arquitecturas de datos en la nube (AWS, Azure y GCP), construir pipelines ETL/ELT escalables mediante Databricks, PySpark y Apache Airflow, y desplegar flujos contenerizados con Docker/Kubernetes y MLOps que alimenten modelos analíticos y tableros ejecutivos.', 'Ingeniero de Datos (Data Engineer), Científico de Datos (Data Scientist), Machine Learning / AI Engineer, Analista de BI & Visualización', 'En el Observatorio de Empleo UniCafam (corte 2026-10-28), la mediana salarial del Mercado Local (Colombia - COP) es de 4,478,000 COP/mes (n = 542 ofertas, n_con_salario = 133), y la del Mercado Internacional (Remoto - USD) es de 14,600,000 COP/mes (n = 28 ofertas, n_con_salario = 11; pocas ofertas internacionales publican salario, por lo que su mediana es poco confiable). En el análisis de primas por rol, Científico de Datos (Data Scientist) es la categoría de referencia (0.0 %, n = 60 ofertas con salario), mientras que Analista de Datos (Data Analyst) presenta una prima salarial concluyente de -32.7 % (IC 95 %: -42.0 % a -22.0 %, q_bh = 0.0, resultado = ''Sí'', n = 41 ofertas con salario). Para Ingeniero de Datos (Data Engineer) (n = 11 ofertas con salario, resultado = ''No evaluable (n < 20)''), Analista de BI & Visualización (n = 10, resultado = ''No evaluable (n < 20)'') y Machine Learning / AI Engineer (prima_pct = -9.4 %, IC 95 %: -24.4 % a 8.6 %, q_bh = 0.2848, resultado = ''No'', n = 39), el observatorio no tiene una prima concluyente en el corte 2026-10-28.', 'https://jfbernalp.dev/downloads/mig/PROP_05_MIG.xlsx', 'PENDIENTE_REVISION', 1, '', '', '');
INSERT INTO historial_revisiones_curriculo (id_propuesta, version_resultante, usuario_aprobador, rol_usuario, decision, comentarios_feedback, cambios_aplicados_resumen, fecha_registro) VALUES ('PROP_05', 1, 'Administrador General del Observatorio', 'Usuario Administrador', 'CREACION_INICIAL', 'Propuesta solicitada desde el portal (Diplomado, 15 créditos, enfoque: arquitectura en nuve. Indicaciones: Este diplomado tiene como objetivo dar a los estudiantes una opcion de grado que permita fortalecer su conocimiento en nube y procesos etl).', '', '2026-10-29 01:04:25');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_05', 1, 'Fundamentos de Arquitecturas Cloud e Ingeniería de Procesos ETL en AWS', '5', 3, 48, 96, 144, '1. Patrones de arquitectura de datos en la nube (Data Lakes, Data Warehouses, ELT vs. ETL) y gobierno del dato.
2. Almacenamiento distribuido en Amazon S3, catálogos de metadatos y particionamiento eficiente.
3. Construcción de pipelines ETL serverless con AWS Glue, Python y consultas federadas con Amazon Athena.
4. Modelado dimensional en la nube con Amazon Redshift e integración desde fuentes relacionales y APIs.', 'Semanas 1 a 3', 'AWS (S3, Glue, Athena, Redshift), Python, SQL, Git / Control de Versiones', 'Diseñar arquitecturas de almacenamiento y procesamiento en AWS aplicando patrones de particionamiento y catalogación para grandes volúmenes de datos. | Implementar procesos ETL automatizados utilizando AWS Glue, Python y SQL para transformar datos crudos en modelos analíticos.', 'Orientado al rol de Ingeniero de Datos (Data Engineer) (25.6 % del mercado, n = 146 de 570 ofertas, corte 2026-10-28), donde ETL / Pipelines de Datos se exige en el 82.9 % de las ofertas del rol, SQL en el 78.8 %, Python en el 62.3 % y AWS en el 44.5 %. En el total del mercado (n = 570 ofertas, corte 2026-10-28), SQL aparece en el 62.3 % (n = 355), Python en el 56.7 % (n = 323), ETL / Pipelines de Datos en el 45.4 % (n = 259), AWS en el 23.5 % (n = 134) y Git / Control de Versiones en el 14.6 % (n = 83).');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_05', 2, 'Arquitecturas Lakehouse y Procesamiento Distribuido con Azure y Databricks', '5', 3, 48, 96, 144, '1. Ecosistema de datos en Microsoft Azure: Azure Data Lake Storage Gen2 (ADLS) y Azure Data Factory para ingesta masiva.
2. Arquitectura Medallion (Bronze, Silver, Gold) y gestión transaccional con Delta Lake sobre Databricks.
3. Optimización de pipelines ETL distribuidos con Spark / PySpark y Spark SQL en entornos colaborativos de nube.
4. Integración del Lakehouse con flujos de trabajo de Ciencia de Datos y Analítica de BI.', 'Semanas 4 a 6', 'Azure (Data Factory, ADLS Gen2), Databricks, Spark / PySpark, SQL, Python', 'Construir pipelines de ingesta y transformación en Microsoft Azure integrando servicios nativos con arquitecturas Lakehouse. | Optimizar procesos ETL distribuidos utilizando Spark / PySpark y Databricks bajo el estándar de capas Medallion.', 'Cierra la principal brecha de nube del currículo: Azure aparece en el 24.0 % de las ofertas totales (n = 137 de 570, corte 2026-10-28) y Databricks en el 16.8 % (n = 96 de 570), articulándose con la fortaleza institucional en Spark / PySpark (18.6 %, n = 106 de 570). Para el rol de Ingeniero de Datos (25.6 %, n = 146), Azure se solicita en el 36.3 % de sus vacantes, Spark / PySpark en el 36.3 % y Databricks en el 33.6 %; para Científico de Datos (31.2 %, n = 178), Azure representa el 24.7 % de las ofertas del rol.');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_05', 3, 'Almacenamiento Analítico en Google Cloud (GCP) y Modern Data Stack', '5', 3, 48, 96, 144, '1. Ingesta y almacenamiento en Google Cloud Storage (GCS) e integración de flujos batch y streaming en GCP.
2. Arquitectura de Data Warehouse serverless con BigQuery: particionamiento, clustering y optimización de costos en SQL.
3. Transformación modular de datos en la nube (paradigma ELT) e integración con bases de datos NoSQL.
4. Capa semántica y conexión de arquitecturas GCP con herramientas de BI y visualización (Looker, Power BI y Tableau).', 'Semanas 7 a 9', 'Google Cloud (GCP) (Cloud Storage, BigQuery), Looker, Power BI, Tableau, SQL, Bases de Datos NoSQL', 'Implementar bodegas de datos analíticas en Google Cloud Platform (GCP) optimizando consultas de alto rendimiento en BigQuery. | Integrar salidas de pipelines ELT en la nube con plataformas de visualización y capa semántica para el soporte a la toma de decisiones.', 'Google Cloud (GCP) es la tercera brecha más demandada con el 19.1 % del mercado general (n = 109 de 570 ofertas, corte 2026-10-28) y el 28.8 % dentro del rol de Ingeniero de Datos (n = 146). Asimismo, conecta con el rol de Analista de BI & Visualización (7.5 %, n = 43 de 570 ofertas), el cual exige SQL (83.7 %), Power BI (76.7 %), Python (65.1 %), ETL / Pipelines de Datos (44.2 %) y Tableau (32.6 %), incorporando además Looker, presente en el 7.0 % de las ofertas totales (n = 40 de 570).');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_05', 4, 'Orquestación de Pipelines de Datos con Apache Airflow y Contenedores (Docker / Kubernetes)', '5', 3, 48, 96, 144, '1. Diseño de grafos acíclicos dirigidos (DAGs) en Apache Airflow: operadores, sensores, dependencias y manejo de reintentos.
2. Empaquetado y despliegue de procesos ETL reproducibles mediante contenedores Docker.
3. Fundamentos de orquestación de contenedores con Kubernetes aplicados a cargas de trabajo de datos en la nube.
4. Monitoreo de calidad de datos, observabilidad, logging e integración continua con Git / Control de Versiones.', 'Semanas 10 a 12', 'Airflow, Docker / Kubernetes, Python, ETL / Pipelines de Datos, Git / Control de Versiones', 'Orquestar flujos de trabajo ETL complejos en la nube programando DAGs modulares y resilientes en Apache Airflow. | Desplegar servicios de procesamiento de datos en entornos contenerizados utilizando Docker y Kubernetes.', 'Atiende las brechas de la categoría Data Engineering & Ops identificadas en el Observatorio (corte 2026-10-28, n = 570 ofertas): Airflow aparece en el 9.3 % de las ofertas (n = 53 de 570) y Docker / Kubernetes en el 5.1 % (n = 29 de 570), complementando la demanda transversal de ETL / Pipelines de Datos (45.4 %, n = 259), Python (56.7 %, n = 323) y Git / Control de Versiones (14.6 %, n = 83).');
INSERT INTO fact_modulos_propuestas_mig (id_propuesta, numero_modulo, nombre_modulo, semestre_sugerido, creditos, horas_tfd, horas_tti, horas_totales_modulo, contenido_detallado, cronograma_fechas, stack_tecnologico, raes, justificacion_mercado) VALUES ('PROP_05', 5, 'MLOps, Despliegue en Nube y Proyecto Integrador de Opción de Grado', '5', 3, 48, 96, 144, '1. Fundamentos de MLOps en la nube: acoplamiento de pipelines ETL con el ciclo de vida de modelos en Scikit-Learn.
2. Registro de experimentos, Feature Stores en la nube y despliegue de pipelines de inferencia por lotes y en línea.
3. Desarrollo y sustentación del Proyecto de Opción de Grado: arquitectura de datos cloud end-to-end (ingesta, ETL distribuido, orquestación, almacenamiento analítico y consumo en ML/BI).
4. Documentación técnica de arquitectura, evaluación de costos cloud y entrega de repositorio reproducible.', 'Semanas 13 a 16', 'MLOps, Scikit-Learn, Azure / AWS / GCP, Databricks, Airflow, Power BI', 'Integrar prácticas de MLOps sobre arquitecturas de datos en la nube para automatizar el entrenamiento y despliegue de modelos analíticos con Scikit-Learn. | Sustentar un proyecto integrador de arquitectura en la nube y procesos ETL que resuelva un problema real de ingeniería y ciencia de datos.', 'Articula la ingeniería de datos en nube con los roles de Científico de Datos (Data Scientist) (31.2 %, n = 178 de 570 ofertas, corte 2026-10-28) y Machine Learning / AI Engineer (18.2 %, n = 104 de 570 ofertas), donde Machine Learning General se solicita en el 42.1 % y 37.5 % de las ofertas de cada rol, y ETL / Pipelines de Datos en el 34.3 % y 32.7 %, respectivamente. Cubre además las brechas en MLOps (7.4 %, n = 42 de 570 ofertas) y Scikit-Learn (6.1 %, n = 35 de 570 ofertas).');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_05', 'Especialista / Magíster en Cloud Data Engineering (AWS)', 'Fundamentos de Arquitecturas Cloud e Ingeniería de Procesos ETL en AWS', 'Ingeniero de Sistemas o de Datos con posgrado en áreas afines, certificación oficial en AWS Data Analytics / Data Engineer y experiencia mínima de 3 años diseñando pipelines ETL con AWS Glue, S3, Athena y Redshift.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_05', 'Especialista / Magíster en Big Data & Arquitecturas Lakehouse (Azure & Databricks)', 'Arquitecturas Lakehouse y Procesamiento Distribuido con Azure y Databricks', 'Profesional con posgrado en Ingeniería de Datos o Ciencia de Datos, certificado en Microsoft Azure Data Engineer Associate y/o Databricks Data Engineer, con experiencia en proyectos industriales sobre PySpark y Delta Lake.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_05', 'Especialista / Magíster en Arquitecturas Analíticas sobre Google Cloud (GCP)', 'Almacenamiento Analítico en Google Cloud (GCP) y Modern Data Stack', 'Profesional con posgrado en Analítica o Ingeniería de Software, experiencia comprobada en diseño de Data Warehouses sobre BigQuery, ecosistemas GCP y conexión con herramientas de visualización empresarial (Looker, Power BI, Tableau).');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_05', 'Especialista / Magíster en DataOps e Infraestructura de Datos', 'Orquestación de Pipelines de Datos con Apache Airflow y Contenedores (Docker / Kubernetes)', 'Ingeniero con posgrado y experiencia práctica liderando la automatización de plataformas de datos en producción mediante Apache Airflow, Docker, Kubernetes y flujos CI/CD.');
INSERT INTO dim_docentes_propuestas_mig (id_propuesta, nombre_o_rol, modulo_asignado, perfil_experto) VALUES ('PROP_05', 'Magíster en Ciencia de Datos / MLOps & Cloud Architect (Director de Opción de Grado)', 'MLOps, Despliegue en Nube y Proyecto Integrador de Opción de Grado', 'Magíster en Ciencia de Datos, Inteligencia Artificial o Ingeniería de Sistemas con experiencia en despliegue de modelos en la nube (MLOps, Scikit-Learn) y dirección de proyectos aplicados de ingeniería y arquitectura de datos.');

-- Vistas para Apache Superset
CREATE OR REPLACE VIEW view_superset_oferta_academica_mig AS
SELECT 
    p.id_propuesta,
    p.tipo_propuesta,
    p.nombre_programa,
    p.titulo_otorgado,
    p.nivel_academico,
    p.modalidad,
    p.duracion_estimada,
    p.creditos_totales,
    p.horas_totales,
    p.horario,
    p.fecha_inicio_estimada,
    p.proximas_ediciones,
    p.inversion_publico_externo,
    p.inversion_comunidad_unicafam,
    p.inversion_egresados,
    p.inversion_grupos,
    p.impacto_salarial_proyectado,
    p.roles_objetivo,
    p.justificacion_detallada,
    p.objetivos_programa,
    p.metodologia_detallada,
    p.valores_agregados,
    COUNT(m.id_modulo) AS total_modulos,
    p.url_descarga_excel,
    ('<a href="' || COALESCE(p.url_descarga_excel, '#') || '" target="_blank" style="background-color: #1F4E79; color: white; padding: 6px 12px; border-radius: 4px; text-decoration: none; font-weight: bold; display: inline-block;">📥 Descargar MIG (.xlsx)</a>') AS boton_descarga_html
FROM dim_propuestas_curriculares_mig p
LEFT JOIN fact_modulos_propuestas_mig m ON p.id_propuesta = m.id_propuesta
GROUP BY 
    p.id_propuesta, p.tipo_propuesta, p.nombre_programa, p.titulo_otorgado, p.nivel_academico,
    p.modalidad, p.duracion_estimada, p.creditos_totales, p.horas_totales, p.horario,
    p.fecha_inicio_estimada, p.proximas_ediciones, p.inversion_publico_externo,
    p.inversion_comunidad_unicafam, p.inversion_egresados, p.inversion_grupos,
    p.impacto_salarial_proyectado, p.roles_objetivo, p.justificacion_detallada,
    p.objetivos_programa, p.metodologia_detallada, p.valores_agregados, p.url_descarga_excel;

CREATE OR REPLACE VIEW view_superset_malla_curricular_mig AS
SELECT 
    m.id_modulo,
    p.id_propuesta,
    p.nombre_programa,
    p.tipo_propuesta,
    p.nivel_academico,
    m.numero_modulo,
    m.nombre_modulo,
    m.creditos,
    m.horas_tfd,
    m.horas_tti,
    m.horas_totales_modulo,
    m.cronograma_fechas,
    m.stack_tecnologico,
    m.raes,
    m.justificacion_mercado,
    d.nombre_o_rol AS docente_asignado,
    d.perfil_experto AS perfil_docente_experto
FROM fact_modulos_propuestas_mig m
JOIN dim_propuestas_curriculares_mig p ON m.id_propuesta = p.id_propuesta
LEFT JOIN dim_docentes_propuestas_mig d ON m.id_propuesta = d.id_propuesta AND m.nombre_modulo = d.modulo_asignado;

CREATE OR REPLACE VIEW view_superset_kpis_curriculares_mig AS
SELECT 
    d.id,
    d.programa_evaluado,
    d.puntuacion_competitividad AS indice_competitividad_mercado,
    (SELECT COUNT(*) FROM dim_propuestas_curriculares_mig) AS total_propuestas_generadas,
    (SELECT SUM(creditos_totales) FROM dim_propuestas_curriculares_mig) AS total_creditos_ofertados,
    (SELECT SUM(horas_totales) FROM dim_propuestas_curriculares_mig) AS total_horas_formacion,
    (SELECT COUNT(*) FROM fact_modulos_propuestas_mig) AS total_modulos_disenados,
    d.resumen_ejecutivo,
    d.fecha_generacion
FROM fact_diagnostico_ia d
ORDER BY d.fecha_generacion DESC
LIMIT 1;